  "prediction_basis_card_ids": ["C09","C29","C19","C33","C35","C37","C38","C32","C34","C40","C41"],
  "claims": [
    {
      "claim": "The query is a close linezolid analog sharing the 2-oxazolidinone core and N-aryl morpholine motif; linezolid has a measured absolute oral bioavailability of 93.01 ± 23.34% after 600 mg tablets in fasted healthy subjects and is reported as almost 100% bioavailable in fasted healthy volunteers.",
      "card_ids": ["C09","C29"]
    },
    {
      "claim": "L3 oral exposure records for linezolid show substantial systemic exposure after oral dosing (median Cmax 18.3–18.9 µg/mL at 600 mg daily; mean Cmax 11.9 mg/L in elderly patients; AUCtau 99.2 µg·h/mL after 500 mg multiple dosing), consistent with high oral absorption.",
      "card_ids": ["C33","C35","C37","C38"]
    },
    {
      "claim": "Tedizolid, another oxazolidinone, achieved oral AUC 20.4–26.1 µg·h/mL versus IV 23.5–30.5 µg·h/mL and oral Cmax 2.25 versus IV 3.02 µg/mL after 200 mg phosphate prodrug, indicating oral exposure approximately 75–91% of IV and supporting class-level high oral bioavailability.",
      "card_ids": ["C32","C34","C40","C41"]
    },
    {
      "claim": "No visible record provides affirmative evidence for F < 20%; the closest-context quantitative F values are ≥27% or qualitative reports are good/high, and the L3 exposure records do not reveal a low-F liability for the query scaffold.",
      "card_ids": ["C09","C29","C19","C32","C34","C40","C41"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C33","C35","C37","C38"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C32","C34","C40","C41"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C30","C31","C36","C39"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "The query differs from linezolid at the amide substituent (5-chlorothiophene-2-carbonyl vs acetyl), the morpholine ring (3-one vs unsubstituted), and the absence of the aryl fluorine; these changes could affect absorption, solubility, or first-pass metabolism.",
    "No experimental solubility, permeability, efflux, or metabolic stability data are available for the query.",
    "The query's prandial state and formulation are unspecified, while the closest linezolid F values were obtained under fasted conditions with tablets.",
    "L3 records are oral exposure measurements, not absolute F determinations for the query; tedizolid, ketoconazole, and dolutegravir records are less structurally relevant, and the dolutegravir records involve drug-drug interactions rather than intrinsic F."
  ],
  "decision_summary": "Prediction remains high: the query is a close linezolid analog, and linezolid has measured absolute F of 93.01 ± 23.34% and is reported almost 100% bioavailable; L3 adds oral exposure records for linezolid (Cmax 18.3–18.9 µg/mL at 600 mg daily; AUCtau 99.2 µg·h/mL after 500 mg) and tedizolid oral/IV comparisons (oral AUC ~86–91% of IV), further supporting high oral bioavailability. No affirmative evidence for F <20% is present, so confidence remains high."
}

